static const char *ROOM_TABS[4] = {"客厅", "书房", "卧室", "电器"};

static const lv_font_t *font_regular(const sh_ui_t *ui)
{
    return ui->options.font_regular ? ui->options.font_regular : LV_FONT_DEFAULT;
}

static const lv_font_t *font_medium(const sh_ui_t *ui)
{
    return ui->options.font_medium ? ui->options.font_medium : font_regular(ui);
}

static const lv_font_t *font_large(const sh_ui_t *ui)
{
    return ui->options.font_large ? ui->options.font_large : font_medium(ui);
}

static lv_obj_t *make_text(sh_ui_t *ui, lv_obj_t *parent,
                           const char *text, int x, int y, int w,
                           const lv_font_t *font, uint32_t color)
{
    lv_obj_t *label = lv_label_create(parent);
    lv_label_set_text(label, text);
    lv_obj_set_pos(label, x, y);
    if(w > 0) lv_obj_set_width(label, w);
    lv_obj_set_style_text_font(label, font ? font : font_regular(ui), 0);
    lv_obj_set_style_text_color(label, lv_color_hex(color), 0);
    lv_obj_set_style_text_opa(label, LV_OPA_COVER, 0);
    return label;
}

static void glass_style(lv_obj_t *obj, int radius, lv_opa_t alpha)
{
    lv_obj_set_style_radius(obj, radius, 0);
    lv_obj_set_style_bg_color(obj, lv_color_hex(COL_GLASS), 0);
    lv_obj_set_style_bg_opa(obj, alpha, 0);
    lv_obj_set_style_border_width(obj, 1, 0);
    lv_obj_set_style_border_color(obj, lv_color_hex(COL_EDGE), 0);
    lv_obj_set_style_border_opa(obj, 92, 0);
    lv_obj_set_style_outline_width(obj, 0, 0);
    lv_obj_set_style_pad_all(obj, 0, 0);
    lv_obj_set_style_shadow_width(obj, 0, 0); /* avoid costly soft shadow */
}

static void style_card(sh_ui_t *ui, uint8_t index)
{
    lv_obj_t *card = ui->cards[index];
    if(!card) return;
    const bool selected = index == ui->active_device;
    lv_obj_set_style_bg_color(card,
        lv_color_hex(selected ? COL_SELECTED : COL_GLASS), 0);
    lv_obj_set_style_bg_opa(card, selected ? 100 : 55, 0);
    lv_obj_set_style_border_color(card,
        lv_color_hex(selected ? 0xC9E3FF : COL_EDGE), 0);
    lv_obj_set_style_border_opa(card, selected ? 210 : 108, 0);
    lv_obj_set_style_border_width(card, selected ? 2 : 1, 0);
}

static void style_tab(sh_ui_t *ui, uint8_t index)
{
    const bool selected = index == ui->active_tab;
    lv_obj_t *tab = ui->tabs[index];
    if(!tab) return;
    lv_obj_set_style_bg_color(tab,
        lv_color_hex(selected ? 0xC0D0E5 : 0xA3B3C7), 0);
    lv_obj_set_style_bg_opa(tab, selected ? 95 : 15, 0);
    lv_obj_set_style_border_width(tab, selected ? 1 : 0, 0);
    lv_obj_set_style_border_color(tab, lv_color_hex(0xE6F0FF), 0);
    lv_obj_set_style_border_opa(tab, 100, 0);
}

static void style_action(sh_ui_t *ui, uint8_t i)
{
    lv_obj_t *btn = ui->action_buttons[i];
    if(!btn) return;
    const bool primary = (i == 0);
    const bool selected = (i == ui->active_action && i > 1);
    lv_obj_set_style_bg_color(btn,
        lv_color_hex(primary ? 0xDFEDFF : 0xA5B6CB), 0);
    lv_obj_set_style_bg_opa(btn, primary ? LV_OPA_COVER : 50, 0);
    lv_obj_set_style_border_width(btn, selected ? 2 : 1, 0);
    lv_obj_set_style_border_color(btn,
        lv_color_hex(selected ? 0xFFFFFF : 0xD6E6F8), 0);
    lv_obj_set_style_border_opa(btn, selected ? LV_OPA_COVER : 55, 0);
    lv_obj_set_style_text_color(btn,
        lv_color_hex(primary ? COL_ACCENT : COL_WHITE), 0);
}

static void refresh_footer(sh_ui_t *ui)
{
    const sh_device_def_t *def = &DEVICES[ui->active_device];
    char title[48];
    size_t n = 0;
    for(const char *p = def->name; *p && n < sizeof(title)-1; p++) {
        if(*p != '\n') title[n++] = *p;
    }
    title[n] = 0;
    lv_label_set_text(ui->footer_label, title);
    for(int i=0; i<SH_ACTION_COUNT; i++) {
        lv_label_set_text(ui->action_labels[i], def->actions[i]);
        style_action(ui, (uint8_t)i);
    }
}

static void on_card_click(lv_event_t *event)
{
    sh_binding_t *b = lv_event_get_user_data(event);
    sh_ui_t *ui = b->ui;
    ui->active_device = b->idx;
    ui->active_action = 2;
    for(int i=0;i<SH_DEVICE_COUNT;i++) style_card(ui, (uint8_t)i);
    refresh_footer(ui);
    if(ui->options.callback) {
        ui->options.callback(b->idx, SH_ACTION_DEVICE_SELECTED,
                             ui->options.user_data);
    }
}

static void on_tab_click(lv_event_t *event)
{
    sh_binding_t *b = lv_event_get_user_data(event);
    b->ui->active_tab = b->idx;
    for(int i=0; i<4; i++) style_tab(b->ui, (uint8_t)i);
    /* Demo changes tab selection only. Application integrates room filtering. */
}

static void on_action_click(lv_event_t *event)
