    sh_binding_t *b = lv_event_get_user_data(event);
    sh_ui_t *ui = b->ui;
    ui->active_action = b->idx;
    for(int i=0;i<SH_ACTION_COUNT;i++) style_action(ui, (uint8_t)i);
    if(ui->options.callback) {
        ui->options.callback(ui->active_device,
              (sh_action_t)(SH_ACTION_CONTROL_0 + b->idx), ui->options.user_data);
    }
}

static void on_mode_click(lv_event_t *event)
