#include "lvgl.h"
#include "smart_home_ui.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define W 1024
#define H 600
static uint8_t fb[W * H * 4];

static void flush_cb(lv_display_t *disp, const lv_area_t *area, uint8_t *px_map)
{
    int32_t w = lv_area_get_width(area);
    for(int32_t y = area->y1; y <= area->y2; y++) {
        memcpy(&fb[(size_t)y * W * 4 + (size_t)area->x1 * 4], px_map, (size_t)w * 4);
        px_map += (size_t)w * 4;
    }
    lv_display_flush_ready(disp);
}

static void cb(uint8_t dev, sh_action_t action, void *ud)
{
    (void)ud;
    printf("EVENT device=%u action=%d\n", dev, (int)action);
}

static void dump(const char *path)
{
    FILE *f = fopen("/tmp/sh_shot/frame.raw", "wb");
    fwrite(fb, 1, sizeof(fb), f);
    fclose(f);
    printf("frame %s (%s)\n", path, "written");
}

int main(int argc, char **argv)
{
    lv_init();
    lv_display_t *disp = lv_display_create(W, H);
    static uint8_t drawbuf[W * H * 4];
    lv_display_set_buffers(disp, drawbuf, NULL, sizeof(drawbuf), LV_DISPLAY_RENDER_MODE_FULL);
    lv_display_set_flush_cb(disp, flush_cb);

    if(lv_freetype_init(1024) != LV_RESULT_OK) { printf("freetype init failed\n"); return 2; }
    const char *font_path = "/usr/share/fonts/opentype/noto/NotoSansCJK-Regular.ttc";
    lv_font_t *f16 = lv_freetype_font_create(font_path, LV_FREETYPE_FONT_RENDER_MODE_BITMAP, 16, LV_FREETYPE_FONT_STYLE_NORMAL);
    lv_font_t *f19 = lv_freetype_font_create(font_path, LV_FREETYPE_FONT_RENDER_MODE_BITMAP, 19, LV_FREETYPE_FONT_STYLE_NORMAL);
    lv_font_t *f44 = lv_freetype_font_create(font_path, LV_FREETYPE_FONT_RENDER_MODE_BITMAP, 44, LV_FREETYPE_FONT_STYLE_NORMAL);
    if(!f16 || !f19 || !f44) { printf("font create failed\n"); return 2; }

    sh_ui_options_t opts = {
        .font_regular = f16,
        .font_medium = f19,
        .font_large = f44,
        .callback = cb,
        .user_data = NULL,
    };
    sh_ui_t *ui = sh_ui_create(lv_screen_active(), &opts);
    if(!ui) { printf("ui create failed\n"); return 2; }

    for(int i = 0; i < 40; i++) { lv_timer_handler(); lv_tick_inc(16); }
    lv_refr_now(disp);
    dump("/tmp/sh_shot/default");
    printf("done\n");
    return 0;
}
`;
